contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an address candidateOwner (to compare against c.Owner())
    // and parameters for Command call: target address and calldata, and an amount to send to Command/withdraw/multiplicate.
    function run(address candidateOwner, address target, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Read current Owner and contract balance before any calls
        address beforeOwner = c.Owner();
        uint256 beforeBal = address(c).balance;

        // Try withdraw as this contract (which is NOT the initial Owner unless candidate matches deployer)
        bool withdrewAsTester;
        try c.withdraw{value: 0}() {
            withdrewAsTester = true;
        } catch {
            withdrewAsTester = false;
        }

        // Try Command as this contract, sending 'amount' wei (could be zero)
        bool commandedAsTester;
        try c.Command{value: amount}(target, data) {
            commandedAsTester = true;
        } catch {
            commandedAsTester = false;
        }

        // Now determine whether this contract is the Owner (observable)
        bool isTesterOwner = (beforeOwner == address(this));

        // If this contract was Owner then both calls must succeed (withdraw transfers full balance, Command allowed).
        // If not Owner then both calls must revert.
        // Additionally, if withdraw succeeded as Owner, then contract balance must be zero afterwards.
        // We can observe post-state: Owner getter and address(c).balance
        address afterOwner = c.Owner();
        uint256 afterBal = address(c).balance;

        // Compose the general rule in one assert:
        // - Ownership doesn't change (beforeOwner == afterOwner)
        // - If tester was owner: withdraw and command did not revert OR at least withdraw succeeded (we only tested calls, both should be allowed)
        //   We assert both succeeded when tester is owner.
        // - If tester was not owner: both calls reverted.
        // - If withdraw succeeded (implying caller was Owner), the contract balance became 0.
        assert(
            beforeOwner == afterOwner
            && (isTesterOwner
                ? (withdrewAsTester && commandedAsTester && afterBal == 0)
                : (!withdrewAsTester && !commandedAsTester))
        );
    }

    receive() external payable {}
}

