contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callerAddr will be used as the msg.sender for the attempt by using Command to forward a call;
    // amount is Ether we send when trying to invoke withdraw via Command (or directly by this contract if it is the owner).
    function run(address callerAddr, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Observe initial contract balance and owner
        uint256 beforeBal = address(c).balance;
        address owner = c.Owner();

        // If callerAddr equals this contract (which is the deployer and thus the Owner), call withdraw directly from this contract.
        // Otherwise, attempt to have callerAddr invoke withdraw by using c.Command to call c with calldata for withdraw.
        // Build calldata for withdraw(): its selector is bytes4(keccak256("withdraw()"))
        bytes memory withdrawCalldata = abi.encodeWithSelector(bytes4(keccak256("withdraw()")));

        bool reverted;
        if (callerAddr == address(this)) {
            // this contract is the Owner (constructor of c set Owner = msg.sender which was this contract), so calling should succeed
            try c.withdraw{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // We attempt to make c.Command execute withdraw where msg.sender for the inner call will be c (because Command does adr.call(...)).
            // That's not the same as callerAddr, so to simulate a non-owner external caller we call Command from this contract but pass adr = address(c)
            // and data = withdrawCalldata. The outer sender is this contract (the owner), but the inner call's msg.sender will be c itself.
            // To produce a non-owner caller attempting withdraw, we instead try to have callerAddr invoke withdraw by sending a low-level call to c through Command is impossible because only Owner can call Command.
            // So to test non-owner revert we simply call c.withdraw from this contract after temporarily pretending this contract is not owner cannot be done.
            // Alternative approach: directly try calling c.withdraw from this contract (which is owner) but then also try to call c.withdraw via low-level call with forged msg.sender is impossible.
            // Therefore we check the property that withdraw succeeds iff msg.sender equals c.Owner(): when called by the observed owner address (this) it should not revert; when called by any other address via external low-level call from this contract, the call will revert.

            // Attempt direct low-level call to simulate non-owner: use address(c).call with withdraw calldata and send along Ether from this contract.
            // This low-level call will have msg.sender == address(this) (still owner), so it won't simulate non-owner; thus to create a non-owner call we must rely on the fact that only Owner can call withdraw and any attempt by non-owner would revert.
            // Since we cannot change msg.sender in this environment, we instead assert the invariant in terms we can observe:
            // If a call to withdraw succeeds when invoked by the observed owner (this contract), then the balance after is 0 and the call did not revert.
            // And any attempt to call withdraw from a non-owner (which we cannot perform here) would revert by the require checking msg.sender==Owner.

            // For the purposes of making a reachable assertion that the checker can verify universally, we perform a call as owner and record whether it reverted.
            try c.withdraw{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBal = address(c).balance;

        // General rule to assert:
        // If the caller we used was the Owner (this contract), then withdraw must not revert and must transfer the entire contract balance (becoming 0).
        // If the caller used is not the Owner, we cannot perform that call here, so we assert nothing about that path; instead we assert that when withdraw did not revert, the caller was the Owner and c.balance is 0 afterward.
        assert((!reverted) == (callerAddr == owner) && (!reverted ? afterBal == 0 : afterBal == beforeBal));
    }

    receive() external payable {}
}

