    // single public function taking inputs and possibly sending Ether
    function run(address target, bytes memory data, uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // record balance before calls
        uint balBefore = address(c).balance;

        // Try calling Command as this contract (not the Owner) and capture revert
        bool commandReverted;
        try c.Command{value: sendAmount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        // record balance after Command attempt
        uint balAfterCmd = address(c).balance;

        // Try calling withdraw as this contract (not the Owner) and capture revert
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint balAfterWithdraw = address(c).balance;

        // General rule: if InvMutTest is not the Owner, both calls must revert and c's balance must be unchanged
        // We observe Owner via public getter and balances via address(c).balance
        if (address(this) != deployer) {
            assert(commandReverted && withdrawReverted && balBefore == balAfterCmd && balBefore == balAfterWithdraw);
        } else {
            // If this contract happens to be the Owner (shouldn't in normal checker), then at least balances reflect that Command may have forwarded the sent value
            // Assert that balances are not decreased unless Command succeeded (i.e., not reverted) or withdraw succeeded.
            // In owner case we assert a weaker invariant linking revert flags and balance changes:
            // If Command reverted, balance must be unchanged after Command. If withdraw reverted, balance must be unchanged after withdraw.
            assert((commandReverted ? balBefore == balAfterCmd : true) && (withdrawReverted ? balAfterCmd == balAfterWithdraw : true));
        }
    }

    receive() external payable {}
}

