        // General rule: if the call did not revert, then caller must be Owner — but in this test the caller is InvMutTest,
        // so the only way Command can succeed is if InvMutTest is Owner (i.e., c.Owner == address(this)).
        // If the call reverted, c.balance must be unchanged.
        assert(
            (!reverted && c.Owner() == address(this) && balAfter == balBefore - sendAmount ||
             reverted && balAfter == balBefore)
        );
    }

