contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address possibleOwner, address target, bytes calldata data, uint sendAmt) public payable {
        require(address(this).balance >= sendAmt);

        // Read initial observable state
        address ownerBefore = c.Owner();
        uint balanceBefore = address(c).balance;

        // Attempt withdraw as non-owner (since InvMutTest is the deployer of c, Owner == InvMutTest by construction)
        // To test non-owner behavior we simulate by first ensuring ownerBefore is not equal to a chosen possibleOwner.
        // If possibleOwner equals current owner, flip to a different address by requiring they differ so the property concerns non-owner calls.
        require(possibleOwner != ownerBefore);

        bool withdrewReverted;
        try c.withdraw{value: 0}() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt Command as non-owner, sending sendAmt
        bool commandReverted;
        // ensure contract has enough balance to meaningfully test value forwarding: fund c with sendAmt from this contract if sendAmt>0
        if (sendAmt > 0) {
            // transfer Ether to c by calling its receive
            (bool ok,) = address(c).call{value: sendAmt}(new bytes(0));
            require(ok);
        }
        uint balanceMid = address(c).balance;

        try c.Command{value: sendAmt}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        uint balanceAfter = address(c).balance;

        // General rule asserted:
        // If the caller is not the Owner (which is true here because possibleOwner != ownerBefore and this contract is not using possibleOwner to call),
        // then withdraw and Command must revert and the contract balance must remain unchanged after those calls.
        // We express this by asserting that both calls reverted and balance didn't decrease.
        assert(withdrewReverted && commandReverted && balanceAfter >= balanceBefore && balanceAfter == balanceMid);
    }

    // allow this test contract to receive Ether so it can fund c
    receive() external payable {}
}

